const esc = value => String(value).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function section(s) {
  const paragraphs=(s.body||[]).map(p=>`<p>${esc(p)}</p>`).join('');
  const list=s.kind==='fit'
    ? `<div class="check-grid">${s.items.map((text,i)=>`<label for="fr-outbound-fit-${i}"><input id="fr-outbound-fit-${i}" type="checkbox" data-fit>${esc(text)}</label>`).join('')}</div><div class="tool-output"><span>Préparation</span><strong data-fit-score>0 sur 8 signaux</strong><p data-fit-copy>Clarifiez le profil d’acheteur, le problème et le suivi commercial avant de lancer la campagne.</p></div>`
    : s.items?`<ul>${s.items.map(text=>`<li>${esc(text)}</li>`).join('')}</ul>`:'';
  const table=s.table?`<div class="table-wrap" tabindex="0" aria-label="${esc(s.table.caption)}"><table><caption>${esc(s.table.caption)}</caption><thead><tr>${s.table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${s.table.rows.map(row=>`<tr>${row.map((cell,i)=>i===0?`<th scope="row">${esc(cell)}</th>`:`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'';
  const refs=s.links?`<div class="text-links">${s.links.map(([label,href])=>`<a href="${esc(href)}">${esc(label)} →</a>`).join('')}</div>`:'';
  return `<section id="${s.id}"${s.kind==='fit'?' class="original-tool checklist-tool"':''}><h2>${esc(s.heading)}</h2>${paragraphs}${list}${table}${s.callout?`<aside class="callout">${esc(s.callout)}</aside>`:''}${refs}</section>`;
}
function apply(html,pathname,locale) {
  const route=`/${locale}${pathname}`;const config=pages[route];const link=links[route];
  if(!config&&!link)return html;
  if(config) {
    html=html.replace(/(<div class="breadcrumbs">[\s\S]*?<span>\/\s*<\/span><span>)[^<]*(<\/span><\/div>)/,(_,a,b)=>a+esc(config.eyebrow)+b);
    html=html.replace(/<title>[^<]*<\/title>/,`<title>${esc(config.title)}</title>`)
      .replace(/(<meta (?:name|property)="(?:description|og:description|twitter:description)" content=")[^"]*(">)/g,(_,a,b)=>a+esc(config.description)+b)
      .replace(/(<meta (?:name|property)="(?:og:title|twitter:title)" content=")[^"]*(">)/g,(_,a,b)=>a+esc(config.title)+b)
      .replace(/<header class="hero">[\s\S]*?<\/header>/,`<header class="hero"><p class="eyebrow">${esc(config.eyebrow)}</p><h1>${esc(config.h1)}</h1><p class="answer">${esc(config.answer)}</p><div class="hero-actions"><a class="button" href="https://calendly.com/noahlevybuilds/30min">${esc(config.primary)}</a><a class="secondary" href="${config.secondary.href}">${esc(config.secondary.label)}</a></div>${meta(locale)}</header>`);
    const faqId=locale==='fr'?'questions-frequentes':'preguntas-frecuentes';
    const faq=`<section class="faqs" id="${faqId}"><h2>${esc(config.faqHeading)}</h2><div class="faq-list">${config.faqs.map(([question,answer])=>`<details><summary>${esc(question)}</summary><p>${esc(answer)}</p></details>`).join('')}</div></section>`;
    html=html.replace(/<article>[\s\S]*?<\/article>/,`<article>${config.sections.map(section).join('')}${faq}</article>`);
    const toc=config.sections.map(s=>`<a href="#${s.id}">${esc(s.heading)}</a>`).join('')+`<a href="#${faqId}">${esc(config.faqHeading)}</a>`;
    html=html.replace(/(<aside class="toc"><div class="toc-label">[\s\S]*?<\/div>)[\s\S]*?(<div class="toc-progress">)/,(_,a,b)=>a+toc+b)
      .replace(/(<details class="mobile-toc">[\s\S]*?<nav[^>]*>)[\s\S]*?(<\/nav><\/details>)/,(_,a,b)=>a+toc+b)
      .replace(/(<strong class="current-section">)[\s\S]*?(<\/strong>)/,(_,a,b)=>a+esc(config.sections[0].heading)+b)
      .replace(/<section class="final-cta">[\s\S]*?<\/section>/,`<section class="final-cta"><h2>${esc(config.finalHeading)}</h2><p>${esc(config.finalCopy)}</p><a class="button" href="https://calendly.com/noahlevybuilds/30min">${esc(config.primary)}</a></section>`);
  } else {
    html=html.replace('</article>',section({id:link.id,heading:link.heading,body:[link.body],links:[[link.label,link.href]]})+'</article>');
    html=html.replace(/<p class="meta">[\s\S]*?<\/p>/,meta(locale));
  }
  html=html.replace(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/,(_,text)=>{
    const schema=JSON.parse(text),graph=schema['@graph'];
    const page=graph.find(n=>n['@id']===origin+route+'#page');
    if(page) { page.dateModified=updated+'T15:00:00+02:00';page.inLanguage=locale;if(config){page.name=config.h1;page.description=config.description;if(page['@type']==='Article')page.headline=config.h1;} }
    if(config){const breadcrumb=graph.find(n=>n['@type']==='BreadcrumbList');if(breadcrumb)breadcrumb.itemListElement.at(-1).name=config.eyebrow;schema['@graph']=graph.filter(n=>n['@type']!=='FAQPage');schema['@graph'].push({'@type':'FAQPage','@id':origin+route+'#faq',inLanguage:locale,mainEntity:config.faqs.map(([question,answer])=>({'@type':'Question',name:question,acceptedAnswer:{'@type':'Answer',text:answer}}))});}
    return `<script type="application/ld+json">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script>`;
  });
  return html;
}
function meta(locale) {return `<p class="meta">${locale==='fr'?'Écrit par':'Escrito por'} <a href="/${locale}/about/noah-levy/">Noah Levy</a> · ${locale==='fr'?'Mis à jour le 15 octobre 2026':'Actualizado el 15 de octubre de 2026'}</p>`;}
function lastModifiedFor(pathname,fallback) {return pages[pathname]||links[pathname]?updated:fallback;}
module.exports={pages,links,apply,lastModifiedFor,updated};
